// @pit: {"label": "Update durable doc paragraph and bump version to 0.36.5"}
async ({ workspace: { search, edit, read } }, p: { cl: string }) => {
  const [d, readme, pkg, lock, cl] = await Promise.all([
    search("(`saved <name>` for `saveOnly`, the error's first line on failure)", { path: "docs/durable.md" }),
    search("pit@v0.36.4", { path: "README.md" }),
    search('"version": "0.36.4"', { path: "package.json" }),
    read("package-lock.json", { limit: 12 }),
    search("## [Unreleased]", { path: "CHANGELOG.md" }),
  ]);
  const dm = d.matches[0];
  const out = [];
  out.push(await edit("docs/durable.md", { revision: dm.revision, changes: [{ kind: "replace", start: dm.anchor, content: dm.text
    .replace("(`saved <name>` for `saveOnly`, the error's first line on failure)", "(`saved <name>` for `saveOnly`, `asked: <title>` for a question, the error's first line on failure)")
    .replace("gives the call's title, the label from the `// @pit:` header or the `label` argument,", "gives the call's title, the label from the `// @pit:` header or the `label` argument (else the program's first line, the `functionId`, or `typescript`),")
    + " Both accept any stored arguments and results, including results pi-durable wrote itself without Pit's details." }] }));
  const lines: string[] = lock.content.split("\n").filter((l: string) => l.includes('"version": "0.36.4"'));
  const changes = lines.map((l) => ({ kind: "replace" as const, start: l.split("|")[0] as `${number}:${string}`, content: l.split("|").slice(1).join("|").replace("0.36.4", "0.36.5") }));
  out.push(await edit("package-lock.json", { revision: lock.revision, changes: [changes[0]!, changes[1]!] }));
  const r = readme.matches[0];
  out.push(await edit("README.md", { revision: r.revision, changes: [{ kind: "replace", start: r.anchor, content: r.text.replace("v0.36.4", "v0.36.5") }] }));
  out.push(await edit("package.json", { revision: pkg.matches[0].revision, changes: [{ kind: "replace", start: pkg.matches[0].anchor, content: pkg.matches[0].text.replace("0.36.4", "0.36.5") }] }));
  out.push(await edit("CHANGELOG.md", { revision: cl.matches[0].revision, changes: [{ kind: "insertAfter", anchor: cl.matches[0].anchor, content: p.cl }] }));
  return out.map((o: any) => `${o.file} ${o.applied}`);
}

// @pit: {"label": "Format changed files and run full validation"}
async ({ delivery: { format, validate } }) => {
  const f = await format();
  const v = await validate({ coverage: true, packageCheck: true });
  return { f: f.formatted, v };
}
